script:
// Custom HTML Block runs inside a shadow DOM; `root_element` (the shadowRoot) is
// provided by frappe.create_shadow_element. Query counts within it, not document.
(function () {
    var root = (typeof root_element !== 'undefined' && root_element) ? root_element : document;

    function set_count(key, value) {
        root.querySelectorAll('.fo-count[data-fo="' + key + '"]').forEach(function (el) {
            el.textContent = value;
        });
    }

    if (!root.querySelectorAll('.fo-count').length) return;

    frappe.db.count('Issue', { filters: { status: ['in', ['Open', 'Submitted', 'In Progress', 'On Hold']] } })
        .then(function (v) { set_count('issues', v); });
    frappe.db.count('Transportation Request', { filters: { workflow_state: ['like', 'Pending%'] } })
        .then(function (v) { set_count('transport', v); });
    frappe.db.count('Visitor').then(function (v) { set_count('visitors', v); });
    frappe.db.count('USIM').then(function (v) { set_count('usim', v); });
})();

// Custom HTML Block runs inside a shadow DOM; `root_element` is provided by
// frappe.create_shadow_element. Query DOM through it, not `document`.
(function () {
    var root = (typeof root_element !== 'undefined' && root_element) ? root_element : document;
    var container = root.querySelector('#pf-cockpit-root');
    if (!container) return;

    var roles = (frappe && frappe.user_roles) || [];
    var is_procurement = roles.some(function (r) {
        return [
            'Procurement Manager - NDMA', 'Procurement Officer', 'Procurement Assistant',
            'Professional Assistant - NDMA', 'PR Verifier', 'Purchase User',
            'Purchase Manager', 'Purchase Master Manager', 'Stock Manager', 'Stock User'
        ].indexOf(r) !== -1;
    });
    var is_accounts = roles.some(function (r) {
        return ['Accounts Manager', 'Accounts User', 'Examination Officer - NDMA'].indexOf(r) !== -1;
    });

    // Ordered per requested layout: Material Request, Purchase Order, Payment Entry.
    var shortcut_defs = [
        {
            key: 'mr', label: 'Material Request', doctype: 'Material Request',
            filter: { status: ['like', '%Pending%'] }, badge_text: 'open',
            badge_bg: 'rgba(253, 234, 196, 0.9)', badge_fg: '#b96b00',
            visible: is_procurement
        },
        {
            key: 'po', label: 'Purchase Order', doctype: 'Purchase Order',
            filter: { status: ['like', '%To Receive%'] }, badge_text: 'to receive',
            badge_bg: 'rgba(220, 220, 246, 0.9)', badge_fg: '#4c4cc7',
            visible: is_procurement
        },
        {
            key: 'pe', label: 'Payment Entry', doctype: 'Payment Entry',
            filter: { docstatus: 0 }, badge_text: 'due',
            badge_bg: 'rgba(255, 229, 232, 0.95)', badge_fg: '#c7475b',
            visible: is_accounts
        }
    ];

    function render_shortcut(s) {
        return '<div class="pf-shortcut" data-key="' + s.key + '" style="padding: 14px 16px; border: 1px solid rgba(0,0,0,0.08); border-radius: 12px; background: rgba(255,255,255,0.6); cursor: pointer;">' +
                 '<div style="display:flex; justify-content:space-between; align-items:center; gap:10px; margin-bottom:4px;">' +
                   '<strong>' + s.label + '</strong>' +
                   '<span style="padding: 3px 9px; border-radius: 999px; background: ' + s.badge_bg + '; color: ' + s.badge_fg + '; font-size: 12px; white-space: nowrap;"><span class="pf-count" data-pf="' + s.key + '">0</span> ' + s.badge_text + '</span>' +
                 '</div>' +
                 '<div style="color: var(--text-muted); font-size: 13px;">Open list →</div>' +
               '</div>';
    }

    function render_card(title, doctypes) {
        var links = doctypes.map(function (dt) {
            return '<div class="pf-card-link" data-dt="' + dt + '" style="padding:5px 0; cursor:pointer; color:var(--text-color);">• ' + dt + '</div>';
        }).join('');
        return '<div style="border:1px solid var(--border-color); border-radius:8px; padding:15px; flex:1; min-width:260px;">' +
               '<strong>' + title + '</strong>' +
               '<div style="margin-top:8px;">' + links + '</div>' +
               '</div>';
    }

    var visible_shortcuts = shortcut_defs.filter(function (s) { return s.visible; });
    var shortcuts_html = visible_shortcuts.map(render_shortcut).join('');

    var html =
        '<h4 style="margin: 10px 0 12px; font-size: 13px; letter-spacing: 0.04em; text-transform: uppercase; color: var(--text-muted);">Your Shortcuts</h4>' +
        '<div id="pf-shortcut-row" style="display: grid; grid-template-columns: repeat(' + Math.max(visible_shortcuts.length, 1) + ', minmax(220px, 1fr)); gap: 12px; margin-bottom: 20px;">' + shortcuts_html + '</div>' +
        '<h4 style="margin: 10px 0 12px; font-size: 13px; letter-spacing: 0.04em; text-transform: uppercase; color: var(--text-muted);">Reports &amp; Masters</h4>' +
        '<div style="display:flex; gap:20px; flex-wrap:wrap;">' +
            (is_procurement ? render_card('Procurement &amp; stores', ['Material Request', 'Purchase Order', 'Purchase Receipt']) : '') +
            (is_accounts ? render_card('Accounts', ['Payment Entry', 'Payroll Entry']) : '') +
        '</div>' +
        ((!is_procurement && !is_accounts) ? '<p>You do not have a role assigned to view anything here.</p>' : '');

    container.innerHTML = html;

    container.querySelectorAll('.pf-shortcut').forEach(function (el) {
        var key = el.getAttribute('data-key');
        var def = shortcut_defs.find(function (s) { return s.key === key; });
        if (!def) return;
        el.addEventListener('click', function () {
            frappe.route_options = def.filter;
            frappe.set_route('List', def.doctype);
        });
    });

    visible_shortcuts.forEach(function (s) {
        frappe.db.count(s.doctype, { filters: s.filter })
            .then(function (v) {
                container.querySelectorAll('.pf-count[data-pf="' + s.key + '"]').forEach(function (el) {
                    el.textContent = v;
                });
            })
            .catch(function (err) { console.error('PF count failed', s.doctype, err); });
    });

    container.querySelectorAll('.pf-card-link').forEach(function (el) {
        el.addEventListener('click', function () {
            frappe.set_route('List', el.getAttribute('data-dt'));
        });
    });
})();
